#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;
    npy_intp n;
    double *weights, *cov, *temp;
    double risk_squared = 0.0;
    int i, j;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    // Ensure arrays are contiguous and of type double
    weights_array = (PyArrayObject*)PyArray_ContiguousFromObject((PyObject*)weights_array, NPY_DOUBLE, 1, 1);
    if (!weights_array) return NULL;

    cov_array = (PyArrayObject*)PyArray_ContiguousFromObject((PyObject*)cov_array, NPY_DOUBLE, 2, 2);
    if (!cov_array) {
        Py_DECREF(weights_array);
        return NULL;
    }

    n = PyArray_SIZE(weights_array);

    weights = (double*)PyArray_DATA(weights_array);
    cov = (double*)PyArray_DATA(cov_array);

    // Allocate temp array for S * x
    temp = (double*)malloc(n * sizeof(double));
    if (!temp) {
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return PyErr_NoMemory();
    }

    // Step 1: Calculate S * x (matrix-vector multiply)
    // cov is stored in row-major order: cov[i*n + j]
    for (i = 0; i < n; i++) {
        double row_sum = 0.0;
        for (j = 0; j < n; j++) {
            row_sum += cov[i * n + j] * weights[j];
        }
        temp[i] = row_sum;
    }

    // Step 2: Calculate x^T * temp (dot product)
    for (i = 0; i < n; i++) {
        risk_squared += weights[i] * temp[i];
    }

    free(temp);
    Py_DECREF(weights_array);
    Py_DECREF(cov_array);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *returns_array;
    npy_intp n;
    double *weights, *returns;
    double total_return = 0.0;
    int i;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    // Ensure arrays are contiguous and of type double
    weights_array = (PyArrayObject*)PyArray_ContiguousFromObject((PyObject*)weights_array, NPY_DOUBLE, 1, 1);
    if (!weights_array) return NULL;

    returns_array = (PyArrayObject*)PyArray_ContiguousFromObject((PyObject*)returns_array, NPY_DOUBLE, 1, 1);
    if (!returns_array) {
        Py_DECREF(weights_array);
        return NULL;
    }

    n = PyArray_SIZE(weights_array);

    weights = (double*)PyArray_DATA(weights_array);
    returns = (double*)PyArray_DATA(returns_array);

    // Calculate dot product: x^T * r
    for (i = 0; i < n; i++) {
        total_return += weights[i] * returns[i];
    }

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}
EOF
